PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE curriculum_nodes (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, domain TEXT NOT NULL, parent_id TEXT REFERENCES curriculum_nodes(id), title TEXT NOT NULL, level TEXT NOT NULL, sort_order INTEGER NOT NULL, status TEXT NOT NULL, metadata_json TEXT NOT NULL);
CREATE TABLE problems (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, platform TEXT NOT NULL, external_id TEXT, title TEXT NOT NULL, url TEXT NOT NULL, difficulty TEXT NOT NULL, content_json TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE problem_patterns (problem_id TEXT REFERENCES problems(id), node_id TEXT REFERENCES curriculum_nodes(id), PRIMARY KEY(problem_id,node_id));
CREATE TABLE lessons (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, node_id TEXT REFERENCES curriculum_nodes(id), body_md TEXT NOT NULL, metadata_json TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE design_cases (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, node_id TEXT REFERENCES curriculum_nodes(id), content_json TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE progress (user_id TEXT REFERENCES users(id), item_type TEXT NOT NULL, item_id TEXT NOT NULL, status TEXT NOT NULL, confidence INTEGER NOT NULL, first_studied_at TEXT NOT NULL, last_studied_at TEXT NOT NULL, last_solved_without_hint_at TEXT, time_spent_minutes INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, PRIMARY KEY(user_id,item_type,item_id));
CREATE TABLE problem_attempts (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), problem_id TEXT REFERENCES problems(id), attempted_at TEXT NOT NULL, result TEXT NOT NULL, hint_used INTEGER NOT NULL, minutes INTEGER NOT NULL, notes_md TEXT NOT NULL, code_url TEXT NOT NULL);
CREATE TABLE review_events (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), item_type TEXT NOT NULL, item_id TEXT NOT NULL, reviewed_at TEXT NOT NULL, rating TEXT NOT NULL, prior_interval_days INTEGER NOT NULL, next_interval_days INTEGER NOT NULL, next_review_at TEXT NOT NULL);
CREATE TABLE review_state (user_id TEXT REFERENCES users(id), item_type TEXT NOT NULL, item_id TEXT NOT NULL, due_at TEXT NOT NULL, interval_days INTEGER NOT NULL, successful_reviews INTEGER NOT NULL DEFAULT 0, lapse_count INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,item_type,item_id));
CREATE TABLE notes (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), item_type TEXT NOT NULL, item_id TEXT NOT NULL, title TEXT NOT NULL, body_md TEXT NOT NULL, tags_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE study_sessions (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), started_at TEXT NOT NULL, ended_at TEXT NOT NULL, domain TEXT NOT NULL, item_type TEXT NOT NULL, item_id TEXT NOT NULL, minutes INTEGER NOT NULL);
CREATE TABLE goals (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id), daily_minutes INTEGER NOT NULL, target_track TEXT NOT NULL, weekly_rest_days_json TEXT NOT NULL, timezone TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE mock_sessions (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), type TEXT NOT NULL, started_at TEXT NOT NULL, duration_minutes INTEGER NOT NULL, score_json TEXT NOT NULL, feedback_md TEXT NOT NULL);
CREATE TABLE bookmarks (user_id TEXT REFERENCES users(id), item_type TEXT NOT NULL, item_id TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(user_id,item_type,item_id));
CREATE INDEX review_due ON review_state(user_id,due_at);
CREATE INDEX curriculum_domain ON curriculum_nodes(domain,level);
CREATE INDEX patterns_node ON problem_patterns(node_id);
CREATE INDEX sessions_date ON study_sessions(user_id,started_at);
CREATE INDEX attempts_problem ON problem_attempts(user_id,problem_id,attempted_at);
CREATE INDEX notes_user ON notes(user_id,updated_at);
